#!/usr/bin/env bun
/**
 * Generates src/migrations-generated.ts from ../migrations/*.sql so the
 * bundled `kontextmind serve` ships the schema inline (no filesystem
 * lookups at runtime). The generated file is committed — deterministic,
 * reviewed like a lockfile.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const here = import.meta.dir;
const dir = join(here, "..", "migrations");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".sql"))
  .sort();

const entries = files
  .map((name) => {
    const body = readFileSync(join(dir, name), "utf8");
    return `  { name: ${JSON.stringify(name)}, body: ${JSON.stringify(body)} },`;
  })
  .join("\n");

const out = `// GENERATED by generate-migrations.mjs — do not edit by hand.
import type { MigrationFile } from "../../server/src/migrate";

export const MIGRATIONS: MigrationFile[] = [
${entries}
];
`;
writeFileSync(join(here, "src", "migrations-generated.ts"), out);
console.log(`generated ${files.length} migrations`);
